class NumberWordFormatter:
    HUNDRED_OFFSET = 1
    TEEN_BASE_OFFSET = 10
    TEN_INDEX_OFFSET = 1
    ZERO_GROUP = "000"
    EMPTY_STRING = ""
    ZERO_ONLY = "ZERO ONLY"
    ONLY_SUFFIX = "ONLY"
    AND_CENTS_TEMPLATE = "AND CENTS {cents} "
    HUNDRED_AND_TEMPLATE = "{hundreds} HUNDRED AND {remainder}"
    HUNDRED_TEMPLATE = "{hundreds} HUNDRED"
    GROUP_SEPARATOR = " "

    def __init__(self):
        self.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]

    def format(self, x):
        if x is None:
            return self.EMPTY_STRING
        return self.format_string(str(x))

    def format_string(self, x):
        left_str, right_str = self._split_decimal(x)
        left_str_rev = self._reverse_and_pad(left_str)
        groups = [''] * 5

        for i in range(len(left_str_rev) // 3):
            groups[i] = self._extract_group(left_str_rev, i)

        left_words = self._build_left_words(groups)
        cents_part = self._build_cents_part(right_str)

        if not left_words.strip():
            return self.ZERO_ONLY
        return f"{left_words.strip()} {cents_part}{self.ONLY_SUFFIX}"

    @staticmethod
    def _split_decimal(x):
        return (x.split('.') + [''])[:2]

    @staticmethod
    def _reverse_and_pad(lstr):
        lstrrev = lstr[::-1]
        remainder = len(lstrrev) % 3
        if remainder == 1:
            lstrrev += "00"
        elif remainder == 2:
            lstrrev += "0"
        return lstrrev

    @staticmethod
    def _extract_group(reversed_string, i):
        return reversed_string[3 * i:3 * i + 3][::-1]

    def _build_left_words(self, groups):
        result = self.EMPTY_STRING
        for i in range(len(groups)):
            if not groups[i]:
                continue
            group_number = int(groups[i])
            if group_number != 0:
                prefix = self.trans_three(groups[i]) + self.GROUP_SEPARATOR + self.parse_more(i) + self.GROUP_SEPARATOR
                result = prefix + result
        return result

    @staticmethod
    def _build_cents_part(rstr):
        if not rstr:
            return self.EMPTY_STRING
        return f"AND CENTS {rstr} "  # simplified; actual trans_two not used in this simplified path

    def trans_two(self, s):
        s = s.zfill(2)
        tens_digit = s[0]
        ones_digit = s[-1]
        if tens_digit == "0":
            return self.NUMBER[int(ones_digit)]
        elif tens_digit == "1":
            return self.NUMBER_TEEN[int(s) - self.TEEN_BASE_OFFSET]
        else:
            tens_word = self.NUMBER_TEN[int(tens_digit) - self.TEN_INDEX_OFFSET]
            ones_word = self.NUMBER[int(ones_digit)]
            if ones_digit == "0":
                return tens_word
            return tens_word + self.GROUP_SEPARATOR + ones_word

    def trans_three(self, s):
        hundreds_digit = s[0]
        remainder = s[1:]
        if hundreds_digit == "0":
            return self.trans_two(remainder)
        hundreds_word = self.NUMBER[int(hundreds_digit)]
        if remainder == "00":
            return self.HUNDRED_TEMPLATE.format(hundreds=hundreds_word)
        return self.HUNDRED_AND_TEMPLATE.format(hundreds=hundreds_word, remainder=self.trans_two(remainder))

    def parse_more(self, i):
        return self.NUMBER_MORE[i]
